// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-07-admin-user-approval-consistency.spec.ts, план .qa/e2e/specs/guided-prayer.md (8.13).
// Тикет #a5decf4a · a5decf4a9de744b22c38c93f. Опора: «לראות מידע לגבי מי אישר»; F-102 AC5 (кто утвердил и когда); решение 05.10 — пользователь видит,
// кто утвердил. У пользователя строка «אושר על ידי» без времени (только дата) — находка 07.10, не реджект: сверяем имя и дату.
// Только чтение: в админке — только открытие экрана молитвы. В конце — USER1.
import { expect } from '@wdio/globals';
import { byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { asAdmin, asUser1, backToUser1, openAdminPrayer, sectionStatus, openUserArvit3 } from '../_lib/admin.ts';

describe('Админка в приложении: согласованность с экраном пользователя', () => {
  afterEach(async () => { await toHome(); });

  it('GP-07 Имя и дата утверждения «המעריב ערבים» в админке = строке «אושר על ידי» у USER1 (ערבית אשכנז 3/15) #a5decf4a @prod-safe', async () => {
    try {
      // 1. ADMIN: «ערבית · נוסח אשכנז» → статус «המעריב ערבים»: «מאושר · <имя>, <дата>, <время>».
      await asAdmin();
      await openAdminPrayer('ערבית', 'אשכנז');
      const status = await sectionStatus('המעריב ערבים');
      const m = status.match(/^מאושר\s*·\s*([^,]+?),\s*(\d{1,2}\.\d{1,2}\.\d{4})/);
      expect(m).not.toBeNull();
      const [, approver, date] = m as RegExpMatchArray;

      // 2. USER1: ערבית (אשכנזי) «3 מתוך 15» → «מקור: … · אושר על ידי <имя>, <дата>».
      await asUser1();
      await openUserArvit3();
      await scrollToText('אושר על ידי');
      const line = await byTextMatches('(?s)מקור: .*אושר על ידי .*');
      await expect(line).toBeDisplayed();
      await expect(line).toHaveText(expect.stringContaining(`אושר על ידי ${approver.trim()}, ${date}`));
    } finally {
      await backToUser1();
    }
  });
});
